1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
93	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
94	func currentItemsOfShift(d *Data, shiftID string) []Item {
95		out := []Item{}
96		seen := map[string]bool{}
97		for _, it := range d.Items {
98			if seen[it.ID] {
99				continue
100			}
101			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
102				seen[it.ID] = true
103				out = append(out, it)
104			}
105		}
106		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
107		return out
108	}
109	
110	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
111	
112	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
113	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
114	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
115	// 不同岗位互不影响。
116	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
117		position = clean(position)
118		owner = clean(owner)
119		overlapNote = clean(overlapNote)
120		if err := requireNonEmpty("岗位", position); err != nil {
121			return Shift{}, err
122		}
123		if err := requireNonEmpty("负责人", owner); err != nil {
124			return Shift{}, err
125		}
126		if !end.After(start) {
127			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
128				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
129		}
130	
131		var created Shift
132		err := svc.store.mutate(func(d *Data) error {
133			var overlapping []Shift
134			for _, sh := range d.Shifts {
135				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
136					overlapping = append(overlapping, sh)
137				}
138			}
139			if len(overlapping) > 0 && overlapNote == "" {
140				ids := make([]string, len(overlapping))
141				for i, sh := range overlapping {
142					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
143				}
144				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
145					ErrOverlap, strings.Join(ids, "、"))
146			}
147	
148			d.ShiftSeq++
149			now := svc.now()
150			created = Shift{
151				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
152				Position:  position,
153				Owner:     owner,
154				Start:     start,
155				End:       end,
156				CreatedAt: now,
157			}
158			d.Shifts = append(d.Shifts, created)
159	
160			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
161			for _, sh := range overlapping {
162				if findNote(d, created.ID, sh.ID) != nil {
163					continue
164				}
165				d.NoteSeq++
166				x, y := notePair(created.ID, sh.ID)
167				d.Notes = append(d.Notes, OverlapNote{
168					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
169					Position:  position,
170					ShiftA:    x,
171					ShiftB:    y,
172					Note:      overlapNote,
173					CreatedAt: now,
174				})
175			}
176			return nil
177		})
178		if err != nil {
179			return Shift{}, err
180		}
181		// 返回独立副本：调用方保留的建立结果（关闭时间等指针字段）不与系统
182		// 保存的班次共享内存。
183		return cloneShift(created), nil
184	}
185	
186	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
187	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
188		note = clean(note)
189		if err := requireNonEmpty("重叠说明", note); err != nil {
190			return OverlapNote{}, err
191		}
192		if clean(shiftA) == clean(shiftB) {
193			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
194		}
195	
196		var saved OverlapNote
197		err := svc.store.mutate(func(d *Data) error {
198			sa, _ := findShift(d, clean(shiftA))
199			sb, _ := findShift(d, clean(shiftB))
200			if sa == nil || sb == nil {
201				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
202			}
203			if sa.Position != sb.Position {
204				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
205					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
206			}
207			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
208				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
209					ErrInvalidInput, sa.ID, sb.ID)
210			}
211			d.NoteSeq++
212			x, y := notePair(sa.ID, sb.ID)
213			saved = OverlapNote{
214				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
215				Position:  sa.Position,
216				ShiftA:    x,
217				ShiftB:    y,
218				Note:      note,
219				CreatedAt: svc.now(),
220			}
221			d.Notes = append(d.Notes, saved)
222			return nil
223		})
224		return saved, err
225	}
226	
