461	// CreateHandover 由交班班次向同岗位接班班次发起交接。
462	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
463	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
464	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
465	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
466	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
467	// 要求仅对首次发起生效。
468	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
469		fromShiftID = clean(fromShiftID)
470		toShiftID = clean(toShiftID)
471	
472		var result Handover
473		err := svc.store.mutate(func(d *Data) error {
474			from, _ := findShift(d, fromShiftID)
475			to, _ := findShift(d, toShiftID)
476			if from == nil {
477				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
478			}
479			if to == nil {
480				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
481			}
482			if from.ID == to.ID {
483				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
484			}
485			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
486			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
487			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
488			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
489			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
490			// 存在与交给自身的校验仍在其前。
491			for i := range d.Handovers {
492				if d.Handovers[i].FromShiftID == from.ID {
493					existing := &d.Handovers[i]
494					// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
495					// 不影响系统保存的原交接记录。
496					result = cloneHandover(*existing)
497					if existing.ToShiftID != to.ID {
498						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
499							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
500					}
501					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
502				}
503			}
504	
505			if from.Position != to.Position {
506				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
507					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
508			}
509	
510			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
511			// 交班班次已经结束，重叠区间须有说明。
512			if to.Closed {
513				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
514			}
515			if to.Start.Before(from.Start) {
516				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
517					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
518					from.ID, from.Start.Format(time.RFC3339))
519			}
520			if !from.Closed {
521				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
522					ErrShiftNotClosed, from.ID)
523			}
524			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
525				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
526					ErrOverlap, from.ID, to.ID)
527			}
528	
529			entries := []HandoverEntry{}
530			for i := range d.Items {
531				it := &d.Items[i]
532				if it.CurrentShiftID == from.ID && !it.Closed {
533					entries = append(entries, HandoverEntry{
534						ItemID:      it.ID,
535						Content:     it.Content,
536						Severity:    it.Severity,
537						Constraints: it.Constraints,
538						FollowOwner: it.FollowOwner,
539						Status:      EntryPending,
540					})
541				}
542			}
543			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
544	
545			d.HandoverSeq++
546			now := svc.now()
547			h := Handover{
548				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
549				Position:    from.Position,
550				FromShiftID: from.ID,
551				ToShiftID:   to.ID,
552				CreatedAt:   now,
553				Entries:     entries,
554			}
555			if len(entries) == 0 {
556				// 空清单直接完成。
557				h.CompletedAt = &now
558			}
559			d.Handovers = append(d.Handovers, h)
560			result = cloneHandover(h)
561			return nil
562		})
563		return result, err
564	}
