566	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
567	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
568	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
569	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
570	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
571	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
572	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
573	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
574		handoverID = clean(handoverID)
575		itemID = clean(itemID)
576		operator = clean(operator)
577		reason = clean(reason)
578		trackingNote = clean(trackingNote)
579		nextFollowOwner = clean(nextFollowOwner)
580	
581		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
582			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
583		}
584		if err := requireNonEmpty("操作人", operator); err != nil {
585			return Handover{}, err
586		}
587	
588		var result Handover
589		err := svc.store.mutate(func(d *Data) error {
590			h, _ := findHandover(d, handoverID)
591			if h == nil {
592				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
593			}
594			e, _ := findEntry(h, itemID)
595			if e == nil {
596				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
597			}
598			if e.Status.Received() {
599				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
600					ErrHandoverState, e.ItemID, e.Status.Label())
601			}
602			if e.Status == EntryReturned {
603				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
604				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
605				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
606				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
607					ErrHandoverState, e.ItemID, h.ID)
608			}
609			switch action {
610			case ActionReturn:
611				if err := requireNonEmpty("退回原因", reason); err != nil {
612					return err
613				}
614			case ActionTrack:
615				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
616					return err
617				}
618				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
619					return err
620				}
621			}
622	
623			now := svc.now()
624			switch action {
625			case ActionConfirm:
626				e.Status = EntryConfirmed
627			case ActionTrack:
628				e.Status = EntryTracking
629				e.TrackingNote = trackingNote
630				e.FollowOwner = nextFollowOwner
631			case ActionReturn:
632				e.Status = EntryReturned
633				e.Rounds = append(e.Rounds, ReturnRound{
634					Seq:            len(e.Rounds) + 1,
635					ReturnedAt:     now,
636					ReturnOperator: operator,
637					Reason:         reason,
638				})
639			}
640			e.Operator = operator
641			e.ProcessedAt = &now
642	
643			if action != ActionReturn {
644				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
645				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
646					it.CurrentShiftID = h.ToShiftID
647					if !contains(it.ShiftIDs, h.ToShiftID) {
648						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
649					}
650					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
651					if action == ActionTrack {
652						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
653						it.FollowOwner = nextFollowOwner
654					}
655					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
656				}
657			}
658	
659			if h.Completed() {
660				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
661				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
662				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
663				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
664				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
665				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
666				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
667				// 项无法再处理，完成时间不会被改写。
668				h.CompletedAt = &now
669			}
670			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
671			// 与完成时间）不与系统保存的交接共享内存。
672			result = cloneHandover(*h)
673			return nil
674		})
675		return result, err
676	}
677	
678	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
679	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
680	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
681	
682	func contains(xs []string, x string) bool {
683		for _, v := range xs {
684			if v == x {
685				return true
686			}
687		}
688		return false
689	}
690	
691	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
692	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
693	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
694	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
695	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
696	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
697	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
698		handoverID = clean(handoverID)
699		itemID = clean(itemID)
700		operator = clean(operator)
701		supplement = clean(supplement)
702		if err := requireNonEmpty("操作人", operator); err != nil {
703			return Handover{}, err
704		}
705		if err := requireNonEmpty("补充说明", supplement); err != nil {
706			return Handover{}, err
707		}
708	
709		var result Handover
710		err := svc.store.mutate(func(d *Data) error {
711			h, _ := findHandover(d, handoverID)
712			if h == nil {
713				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
714			}
715			e, _ := findEntry(h, itemID)
716			if e == nil {
717				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
718			}
719			if e.Status != EntryReturned {
720				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
721					ErrHandoverState, e.ItemID, e.Status.Label())
722			}
723			if len(e.Rounds) == 0 {
724				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
725			}
726			round := &e.Rounds[len(e.Rounds)-1]
727			if round.ResubmittedAt != nil {
728				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
729			}
730			now := svc.now()
731			round.Supplement = supplement
732			round.SupplementOperator = operator
733			round.SupplementAt = &now
734			round.ResubmittedAt = &now
735			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
736			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
737			e.Status = EntryPending
738			e.Operator = ""
739			e.ProcessedAt = nil
740			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
741			result = cloneHandover(*h)
742			return nil
743		})
744		return result, err
745	}
746	
747	// GetShift 按编号查询班次。返回独立副本：改动结果不影响系统保存的记录。
748	func (svc *Service) GetShift(id string) (Shift, error) {
749		sh, _ := findShift(&svc.store.data, clean(id))
750		if sh == nil {
751			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
752		}
753		return cloneShift(*sh), nil
754	}
755	
756	// ListShifts 返回全部班次，按编号排序；每个班次都是独立副本。
757	func (svc *Service) ListShifts() []Shift {
758		out := make([]Shift, len(svc.store.data.Shifts))
759		for i, sh := range svc.store.data.Shifts {
760			out[i] = cloneShift(sh)
761		}
762		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
763		return out
764	}
765	
766	// GetItem 按稳定编号查询事项。返回独立副本：流经班次、历史事件与关闭时间
767	// 都与存储中的记录脱离，改动结果不影响系统保存的记录。
768	func (svc *Service) GetItem(id string) (Item, error) {
769		it, _ := findItem(&svc.store.data, clean(id))
770		if it == nil {
771			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
772		}
773		return cloneItem(*it), nil
774	}
775	
776	// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
777	// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
778	func (svc *Service) GetHandover(id string) (Handover, error) {
779		h, _ := findHandover(&svc.store.data, clean(id))
780		if h == nil {
781			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
782		}
783		return cloneHandover(*h), nil
784	}
785	
786	// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
787	func (svc *Service) ListHandovers() []Handover {
788		out := make([]Handover, len(svc.store.data.Handovers))
789		for i, h := range svc.store.data.Handovers {
790			out[i] = cloneHandover(h)
791		}
792		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
793		return out
794	}
795	
796	// OverlapNotes 返回涉及指定班次的全部重叠说明。
797	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
798		shiftID = clean(shiftID)
799		out := []OverlapNote{}
800		for _, n := range svc.store.data.Notes {
801			if n.ShiftA == shiftID || n.ShiftB == shiftID {
802				out = append(out, n)
803			}
804		}
805		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
806		return out
807	}
808	
809	// cloneTimePtr 复制时间指针，nil 保持 nil。
810	func cloneTimePtr(t *time.Time) *time.Time {
811		if t == nil {
812			return nil
813		}
814		v := *t
815		return &v
816	}
817	
818	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
819	func cloneItem(it Item) Item {
820		out := it
821		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
822		out.Events = append([]ItemEvent(nil), it.Events...)
823		out.ClosedAt = cloneTimePtr(it.ClosedAt)
824		return out
825	}
826	
827	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
828	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
829		out := s
830		out.ClosedAt = cloneTimePtr(s.ClosedAt)
831		return out
832	}
833	
834	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
835	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
836	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
837		if rec == nil {
838			return nil
839		}
840		out := &ShiftCloseRecord{}
841		if rec.Items != nil {
842			out.Items = make([]CloseItemSnapshot, len(rec.Items))
843			for i, s := range rec.Items {
844				out.Items[i] = cloneCloseItemSnapshot(s)
845			}
846		}
847		return out
848	}
849	
850	// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
851	func cloneShift(sh Shift) Shift {
852		out := sh
853		out.ClosedAt = cloneTimePtr(sh.ClosedAt)
854		out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
855		return out
856	}
857	
858	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
859	func cloneEntry(e HandoverEntry) HandoverEntry {
860		out := e
861		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
862		if e.Rounds != nil {
863			out.Rounds = make([]ReturnRound, len(e.Rounds))
864			for i, r := range e.Rounds {
865				out.Rounds[i] = r
866				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
867				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
868			}
869		}
870		return out
871	}
872	
873	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
874	func cloneHandover(h Handover) Handover {
875		out := h
876		out.CompletedAt = cloneTimePtr(h.CompletedAt)
877		if h.Entries != nil {
878			out.Entries = make([]HandoverEntry, len(h.Entries))
879			for i, e := range h.Entries {
880				out.Entries[i] = cloneEntry(e)
881			}
882		}
883		return out
884	}
885	
886	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
887	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
888	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
889	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
890	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
891	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
892	// 也不会改写这份报告；再次查询才反映最新内容。
893	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
894		shiftID = clean(shiftID)
895		d := &svc.store.data
896		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
897		sh, _ := findShift(d, shiftID)
898		if sh == nil {
899			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
900		}
901		rep.Shift = cloneShift(*sh)
902	
903		for _, n := range d.Notes {
904			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
905				rep.OverlapNotes = append(rep.OverlapNotes, n)
906			}
907		}
908		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
909	
910		switch {
911		case !sh.Closed:
912			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
913			rep.Items = currentItemsOfShift(d, sh.ID)
914		case sh.CloseRecord != nil:
915			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
916			rep.ItemsAtClose = true
917			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
918			for i, s := range sh.CloseRecord.Items {
919				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
920			}
921			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
922			for _, s := range rep.CloseItems {
923				if it, _ := findItem(d, s.ItemID); it != nil {
924					rep.LatestItems[s.ItemID] = cloneItem(*it)
925				}
926			}
927		default:
928			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
929			rep.HistoryIncomplete = true
930			rep.Items = currentItemsOfShift(d, sh.ID)
931		}
932		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
933		for i := range rep.Items {
934			rep.Items[i] = cloneItem(rep.Items[i])
935		}
936	
937		for i := range d.Handovers {
938			h := &d.Handovers[i]
939			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
940			if !involved {
941				continue
942			}
943			if h.FromShiftID == sh.ID {
944				cp := cloneHandover(*h)
945				rep.Outgoing = &cp
946			}
947			if h.ToShiftID == sh.ID {
948				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
949			}
950			for j := range h.Entries {
951				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
952					HandoverID: h.ID,
953					FromShift:  h.FromShiftID,
954					ToShift:    h.ToShiftID,
955					Entry:      cloneEntry(h.Entries[j]),
956				})
957			}
958		}
959		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
960		for k := range rep.Results {
961			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
962		}
963		return rep, nil
964	}
