2	
3	import (
4		"errors"
5		"os"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// 本文件为“逐项退回”补充保存失败时的可重复回归保障：接班人填了有效操作人、
12	// 非空原因且事项当前允许退回（待处理），但本地数据在原子保存阶段失败。
13	// 通用的快照回滚（store.mutate）适用于退回，但之前没有针对退回的回归测试，
14	// 因此用两个用例分别覆盖首次退回与补充后再次退回这两种使用条件，并沿用既
15	// 有保存失败测试的同一套故障注入方式（在 .tmp 路径放目录使写入必然失败）。
16	
17	// failedReturnExpectations 汇总失败尝试发生前已保存的业务事实，供 reopen
18	// 前后用同一组期望核对。
19	type failedReturnExpectations struct {
20		hID                string
21		fromShift, toShift string
22		idA, idB           string
23		otherConfirmedAt   time.Time // 同交接中另一项已接收的处理时间
24		preRounds          int       // 失败尝试前已成功保存的退回轮次
25		r1ReturnedAt       time.Time // 第一轮成功退回时间
26		r1Reason           string
