344	// 内存与磁盘都回到失败前：该项仍是待处理、接班人尚未处理，不产生退回轮次，
345	// 失败尝试的原因、人名与时刻都不是已发生的退回，交接未完成、无完成时间，接班
346	// 班次不能结束，同交接已确认接收的另一项与交班班次结束时记录不受影响，原数据
347	// 文件一个字节不变。保存恢复后对同一事项重新执行退回，只新增一轮成功记录，
348	// 记录本次成功操作的原因、操作人与实际处理时间；失败尝试不占用轮次、不混入
349	// 经过。成功退回的当前结果明确表示等待交班人补充，事项仍留在交班班次，不因
350	// 这次退回而被接收。
351	func TestReturnSaveFailureFirstAtomicRollback(t *testing.T) {
352		f := newFixture(t)
353		a, b, items := prepareHandover(t, f)
354		h, err := f.svc.CreateHandover(a.ID, b.ID)
355		if err != nil {
356			t.Fatalf("create handover: %v", err)
357		}
358		idA, idB := items[0].ID, items[1].ID // 事项甲、事项乙（事项丙已关闭）
359	
360		// 同交接另一项先成功接收，后续核对它不受失败尝试影响。
