728		// 保留既有规则：交班人就第2轮补充重新提交，接班人确认接收后事项才进入
729		// 接班班次，整份交接在确认时刻才完成。
730		r2ResubmitAt := tsDay(2, 19, 30)
731		f.svc.nowAt(func() time.Time { return r2ResubmitAt })
732		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "第二轮补充-成功提交"); err != nil {
733			t.Fatalf("resubmit round 2: %v", err)
734		}
735		confirmAt := tsDay(2, 20, 0)
736		f.svc.nowAt(func() time.Time { return confirmAt })
737		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
738			t.Fatalf("重新提交后确认接收应成功：%v", err)
739		}
740		h3, err := f.svc.GetHandover(h.ID)
741		if err != nil {
742			t.Fatalf("get handover after confirm: %v", err)
743		}
744		if !h3.Completed() || h3.CompletedAt == nil || !h3.CompletedAt.Equal(confirmAt) {
745			t.Fatalf("全部接收后交接才完成，完成时间应以确认时刻为准：%+v", h3)
746		}
747		ce := findEntryOf(t, h3, idA)
748		if ce.Status != EntryConfirmed || ce.Operator != "李四" ||
749			ce.ProcessedAt == nil || !ce.ProcessedAt.Equal(confirmAt) {
750			t.Fatalf("事项应记录本次确认接收：%+v", ce)
751		}
752		if len(ce.Rounds) != 2 || ce.Rounds[1].Supplement != "第二轮补充-成功提交" {
753			t.Fatalf("两轮退回与成功补充应作为历史保留：%+v", ce.Rounds)
754		}
755		it2, err := f.svc.GetItem(idA)
756		if err != nil {
757			t.Fatalf("get item after confirm: %v", err)
758		}
759		if it2.CurrentShiftID != b.ID || len(it2.ShiftIDs) != 2 {
760			t.Fatalf("确认接收后事项才进入接班班次：%+v", it2)
761		}
762	
763		// 退出重开后，两轮成功退回、补充与最终接收完整保留，失败尝试仍无痕迹。
764		f.reopen(t)
765		h4, err := f.svc.GetHandover(h.ID)
766		if err != nil {
767			t.Fatalf("reopen get handover: %v", err)
768		}
769		if !h4.Completed() || h4.CompletedAt == nil || !h4.CompletedAt.Equal(confirmAt) {
770			t.Fatalf("重开后交接完成状态与完成时间应保留：%+v", h4)
771		}
772		re := findEntryOf(t, h4, idA)
773		if re.Status != EntryConfirmed || len(re.Rounds) != 2 ||
774			re.Rounds[0].Supplement != want.r1Supplement ||
775			re.Rounds[1].Reason != successReason ||
776			re.Rounds[1].Supplement != "第二轮补充-成功提交" {
777			t.Fatalf("重开后两轮退回与补充应完整保留：%+v", re.Rounds)
778		}
779		j4, err := f.svc.ItemJourney(idA)
780		if err != nil {
781			t.Fatalf("reopen journey: %v", err)
782		}
783		if got := joinStrings(journeyKinds(j4)); got != "created,handover-init,return,resubmit,return,resubmit,confirm" {
784			t.Fatalf("重开后处理经过应只保留成功事实，got %s", got)
785		}
786		for _, ev := range j4.Events {
787			if ev.TimeKnown && ev.At.Equal(want.failAt) ||
788				ev.Operator == want.failedOperator ||
789				strings.Contains(ev.Reason, want.failedReason) {
790				t.Fatalf("重开后失败尝试的时刻、人名与原因仍不应出现：%+v", ev)
791			}
792		}
793	
794		// 全部接收后接班班次才能结束。
795		if _, err := f.svc.CloseShift(b.ID); err != nil {
796			t.Fatalf("全部接收后接班班次应能结束：%v", err)
797		}
798	}
799	
800	// TestReturnBlankReasonRejectedWithoutSaving：退回原因为空或只有空白时沿用
801	// 现有必填校验，明确拒绝操作，不留下任何退回事实（不产生轮次、不改当前结果、
802	// 交接仍未完成），也不发生保存。
803	func TestReturnBlankReasonRejectedWithoutSaving(t *testing.T) {
804		f := newFixture(t)
805		a, b, items := prepareHandover(t, f)
806		h, _ := f.svc.CreateHandover(a.ID, b.ID)
807		idA := items[0].ID
808	
809		rawBefore, err := os.ReadFile(f.store.Path())
810		if err != nil {
811			t.Fatalf("read data file: %v", err)
812		}
813		for _, reason := range []string{"", "   ", "\t\n "} {
814			if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", reason, "", ""); !errors.Is(err, ErrInvalidInput) {
815				t.Fatalf("空白退回原因 %q 应按必填校验拒绝，got %v", reason, err)
816			}
817		}
818	
819		got, _ := f.svc.GetHandover(h.ID)
820		e := findEntryOf(t, got, idA)
821		if e.Status != EntryPending || e.Operator != "" || e.ProcessedAt != nil || len(e.Rounds) != 0 {
822			t.Fatalf("校验拒绝不应留下任何退回事实：%+v", e)
823		}
824		if got.Completed() || got.CompletedAt != nil {
825			t.Fatalf("校验拒绝后交接应仍未完成：%+v", got)
826		}
827		it, _ := f.svc.GetItem(idA)
828		if it.CurrentShiftID != a.ID {
829			t.Fatalf("校验拒绝不应移动事项：%+v", it)
830		}
831		rawAfter, err := os.ReadFile(f.store.Path())
832		if err != nil {
833			t.Fatalf("read data file after rejection: %v", err)
834		}
835		if string(rawAfter) != string(rawBefore) {
836			t.Fatalf("校验拒绝不应发生写入、不应改动数据文件")
837		}
838	}
839

