	b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
	var items []Item
	for _, c := range []string{"事项甲", "事项乙", "事项丙"} {
		it, err := f.svc.AddItem(a.ID, c, SeverityNormal, "", "李四")
		if err != nil {
			t.Fatalf("add item: %v", err)
